  int64_t offset;
  int rc = blosc_getitem(coffsets, nchunk, 1, &offset);
  if (rc < 0) {
    size_t nbytes_, cbytes_, blocksize_;
    blosc_cbuffer_sizes(coffsets, &nbytes_, &cbytes_, &blocksize_);
    fprintf(stderr, "Error: problems retrieving a chunk offset");
    return -4;
